    {
      "action": "add_note",
      "params": {
        "note": "Cliente disputa la factura por 40 unidades faltantes; se ha solicitado documentación y se ha copiado a la nueva asesoría de cobros."
      },
      "why": "Registrar la disputa y la solicitud de información."
    },
    {
      "action": "update_status",
      "params": {
        "status": "disputed"
      },
      "why": "Reflejar que la factura está bajo disputa por falta de unidades."
    }
  ]
